<?php require __DIR__.'/../_init.php'; adminHeader('Orders'); ?><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Payment</th></tr><?php foreach($pdo->query('SELECT o.*,u.name FROM orders o JOIN users u ON o.user_id=u.id ORDER BY o.id DESC') as $r): ?><tr><td><a href="view.php?id=<?= (int)$r['id'] ?>">#<?= (int)$r['id'] ?></a></td><td><?= e($r['name']) ?></td><td>৳<?= e($r['total']) ?></td><td><?= e($r['status']) ?></td><td><?= e($r['payment_method'].' / '.$r['payment_status']) ?></td></tr><?php endforeach ?></table><?php adminFooter(); ?>